create table lessons (id uuid primary key default gen_random_uuid(), title text not null, moe_level text not null, week_number int, status text default 'pending', word_list text[] not null, created_at timestamptz default now());
create table submissions (id uuid primary key default gen_random_uuid(), student_id text not null, lesson_id uuid references lessons(id), image_url text not null, total_score int, total_possible int, status text default 'pending', created_at timestamptz default now());
create table character_results (id uuid primary key default gen_random_uuid(), submission_id uuid references submissions(id) on delete cascade, character text not null, is_correct boolean not null, expected_text text, created_at timestamptz default now());
